var defs=[["boarding_music","♫","Musique d’embarquement"],["boarding_welcome","👋","Boarding Welcome"],["boarding_complete","✓","Boarding Complete"],["arm_doors","🔒","Arm Doors"],["presafety_briefing","🎙","Presafety Briefing"],["safety_briefing","🦺","Safety Briefing"],["cabin_dim_takeoff","☾","Cabin Dim Takeoff"],["crew_seat_takeoff","💺","Crew Seat Takeoff"],["after_takeoff_9000","↗","Après décollage · 9 000 ft"],["descent_seatbelt","↘","Descent Seat Belt"],["crew_seat_landing","💺","Crew Seat Landing"],["after_landing","🛬","Après atterrissage"],["disarm_doors","🔓","Disarm Doors"],["disembark_started","🚪","Disembark Started"]];
function e(s){return String(s==null?'':s).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}function number(v,d){return Number.isFinite(v)?Math.round(v).toLocaleString('fr-FR')+(d?' '+d:''):'—'}
