function applyCompanyTheme(f){var code=f&&f.company?String(f.company.icaoCode||'').toUpperCase():'OPS',themes={AFR:['#3f74e8','#e32636'],BAW:['#315ca8','#d7193f'],BTI:['#88d2e8','#8ec63f'],DLH:['#f5c400','#162b55'],EJU:['#ff6600','#273147'],KLM:['#28a7df','#12689a'],RYR:['#f5d328','#1d3f7a'],SWR:['#e21b2d','#83131c'],TRA:['#1fcb79','#006b4f'],TVF:['#1fcb79','#006b4f'],VLG:['#f4d21f','#767676'],VOE:['#ef4870','#7c2141']},theme=themes[code]||['#4d8bff','#133a82'];document.documentElement.style.setProperty('--company-a',theme[0]);document.documentElement.style.setProperty('--company-b',theme[1]);document.documentElement.style.setProperty('--company-glow',theme[0]+'42');document.getElementById('company-watermark').textContent=code}
